\subsection{Radar Channel}
\label{subsec:radar_channel}
This section analyzes the received radar signal. As shown in Fig.~\ref{fig:System-Model}, the radar channel comprises five distinct propagation paths:
\begin{enumerate}
 \item \textbf{BS $\to$ Target $\to$ BS Path:} The signal travels directly from the BS to the target and back to the BS.

 \item \textbf{BS $\to$ Target $\to$ RDARS Path:} The signal propagates from the BS to the target and is then reflected back to the RDARS's connected elements.

 \item \textbf{BS $\to$ Target $\to$ RDARS $\to$ BS Path:} The signal travels from the BS to the target and is then reflected to the RDARS's reflection elements and is finally reflected back to the BS.

 \item \textbf{RDARS $\to$ Target $\to$ RDARS Path:} The signal is transmitted from the RDARS's connected elements to the target and returns to the RDARS.

 \item \textbf{RDARS $\to$ Target $\to$ BS Path:} The signal transmitted from the connected elements of RDARS to the target and is then reflected back to the BS.
\end{enumerate}
The BS, located at $\mathbf{q} \in \mathbb{R}^{2}$, serves $K$ single-antenna users at $\mathbf{u}\in \mathbb{R}^{2}$ while sensing a point target at $\mathbf{p}\in \mathbb{R}^{2}$, aided by an RDARS at $\mathbf{r}\in \mathbb{R}^{2}$. The total received radar signal for subcarrier $n$ is given by:
\begin{equation}
\mathbf{Y}_R[n] = 
\begin{bmatrix}
\alpha_{1}e^{-j2\pi n \Delta f\tau_{1}}{\mathbf{G}}_{1}\mathbf{x}_1[n]

+\alpha_{3}e^{-j2\pi n \Delta f\tau_{3}}{\mathbf{G}}_{3}\mathbf{x}_1[n] 

+\alpha_{5}e^{-j2\pi n \Delta f\tau_{5}}{\mathbf{G}}_{5}\mathbf{x}_2[n] 
\alpha_{2}e^{-j2\pi n \Delta f\tau_{2}}{\mathbf{G}}_{2}\mathbf{x}_1[n]

+\alpha_{4}e^{-j2\pi n \Delta f \tau_{4}}{\mathbf{G}}_{4}\mathbf{x}_2[n] 
\end{bmatrix} +\mathbf{Z}_R[n],
\label{eq:radar_signal} 
\end{equation}
where the path delays are:
\begin{align}
\tau_1 &= \scalebox{0.9}{$\frac{2}{c} \| \mathbf{q} - \mathbf{p} \|_2$}, \label{eq:tau1} 
\tau_2 &= \tau_5 = \scalebox{0.9}{$\frac{1}{c} \left[ \| \mathbf{r} - \mathbf{p} \|_2 + \| \mathbf{q} - \mathbf{p} \|_2 \right]$}, \label{eq:tau2} 
\tau_3 &= \scalebox{0.9}{$\frac{1}{c} \left[ \| \mathbf{q} - \mathbf{r} \|_2 + \| \mathbf{r} - \mathbf{p} \|_2 + \| \mathbf{p} - \mathbf{q} \|_2 \right]$}, \label{eq:tau3} 
\tau_4 &= \scalebox{0.9}{$\frac{2}{c} \| \mathbf{r} - \mathbf{p} \|_2$}. \label{eq:tau4} 
\end{align}
The term \(\Delta f\) denotes the subcarrier spacing and $\mathbf{Z}_{R}[n] \sim \mathcal{CN}(\mathbf{0},\sigma^2\mathbf I)$ represents AWGN. The parameters \(\alpha_k\) denote the complex path gains. Here, \(\theta_1\) is the BS-target angle, \(\theta_2\) is the RDARS-target direction in a global frame, \(\theta_3\) is the BS-RDARS angle in the BS frame, \(\theta_4\) is the RDARS-BS angle in the RDARS frame, and \(\theta_5\) is the same RDARS-target direction expressed in the RDARS local frame. The array orientations are assumed known, so $\theta_5=\theta_2+\psi_0$ for a known frame offset $\psi_0$, and therefore $\partial\theta_5/\partial\theta_2=1$.
The beamforming gain matrices $\mathbf{G}_k$ are defined as follows: $\mathbf{G}_1 = \mathbf{a}(\theta_1) \mathbf{a}^H(\theta_1)$, $\mathbf{G}_2 = \mathbf{A}_a^T \mathbf{b}(\theta_2) \mathbf{a}^H(\theta_1)$, $\mathbf{G}_3 = g \, \mathbf{a}(\theta_1) \mathbf{a}^H(\theta_3)$, $\mathbf{G}_4 = \mathbf{A}_a^T \mathbf{b}(\theta_2) \mathbf{b}^H(\theta_2) \mathbf{A}_a$, and $\mathbf{G}_5 = \mathbf{a}(\theta_1) \mathbf{b}^H(\theta_2) \mathbf{A}_a$.
Where $\mathbf{a}(\cdot)$ denotes the BS array response and $\mathbf{b}_{\text{eff}}(\cdot) = \mathbf{A}_a^T \mathbf{b}_{\text{full}}(\cdot)$ represents the effective array response of the connected RDARS elements. The gain factor \(g\) for path 3 is computed as follows (where \(\mathbf{c}(\cdot)\) corresponds to the RDARS reflected elements array response):
\begin{equation}
g = \mathbf{c}^H(\theta_4) \left[ (\mathbf{I} - \mathbf{A}) \boldsymbol{\Phi} \right] \mathbf{c}(\theta_5).
\label{eq:gain_g}
\end{equation}
\subsection{Performance Metrics}
To evaluate and compare different systems, appropriate performance metrics must be defined. For ISAC systems, these typically fall into two categories: communication metrics (e.g., data rate or SINR) and radar metrics (e.g., target localization accuracy). In this work, we adopt the SINR as the communication metric and the CRB as the radar performance metric. The CRB provides a fundamental lower bound on the covariance matrix of any unbiased estimator \cite{kay1993fundamentals}.
Based on the received signal model in \eqref{eq:radar_signal}, the complete parameter vector \(\boldsymbol{\gamma} \in \mathbb{R}^{12}\) includes both the target position and the path loss coefficients is given by $\boldsymbol{\gamma} = [\mathbf{p}^{T}, \boldsymbol{\alpha}^{T}]^{T}$,
where $\boldsymbol{\alpha} = [\boldsymbol{\alpha}_1^{T}, \boldsymbol{\alpha}_2^{T}, \boldsymbol{\alpha}_3^{T}, \boldsymbol{\alpha}_4^{T}, \boldsymbol{\alpha}_5^{T}]^{T}$ and each sub-vector $\boldsymbol{\alpha}_k$ contains the real and imaginary parts of the path loss coefficient for the $k$-th path, i.e., $\boldsymbol{\alpha}_k = [\Re\{\alpha_k\}, \Im\{\alpha_k\}]^{T}$.
Let $\hat{\boldsymbol{\gamma}}$ be an estimate of $\boldsymbol{\gamma}$ obtained from the observations $\mathbf{Y}_{R}[n]$'s. The Mean Squared Error (MSE) matrix satisfies the inequality \cite{kay1993fundamentals}:
\begin{equation}
\scalebox{0.9}{$\mathbb{E}\left\{ (\hat{\boldsymbol{\gamma}} - \boldsymbol{\gamma})(\hat{\boldsymbol{\gamma}} - \boldsymbol{\gamma})^{T} \right\} \geq \mathbf{J}_{\boldsymbol{\gamma}}^{-1}$},
\label{eq:crb_inequality}
\end{equation}
where \(\mathbf{J}_{\bm{\gamma}}\) is the FIM for \(\boldsymbol{\gamma}\). In particular, for the target position estimate \(\hat{\mathbf{p}}\), (\ref{eq:crb_inequality}) yields a lower bound on the localization MSE:
\begin{equation}
\scalebox{0.9}{$\mathbb{E}\left\{ (\hat{\mathbf{p}} - \mathbf{p})(\hat{\mathbf{p}} - \mathbf{p})^{T} \right\} \geq \textrm{CRB}(\mathbf{p})$}.
\label{eq:position_crb}
\end{equation}
\section{Calculation of the CRB of Target Position}
This section analyzes the fundamental limits of target localization by deriving the corresponding FIM.
Following the received signal model in \eqref{eq:radar_signal}, the complete parameter vector $\boldsymbol{\gamma} \in \mathbb{R}^{12}$ is defined to encapsulate both the target position and the path loss coefficients:
\begin{equation}
\boldsymbol{\gamma} = [\mathbf{p}^{T}, \boldsymbol{\alpha}^{T}]^{T},
\label{eq:parameter_vector}
\end{equation}
where $\boldsymbol{\alpha} = [\boldsymbol{\alpha}_1^{T}, \boldsymbol{\alpha}_2^{T}, \boldsymbol{\alpha}_3^{T}, \boldsymbol{\alpha}_4^{T}, \boldsymbol{\alpha}_5^{T}]^{T}$. Each sub-vector $\boldsymbol{\alpha}_k$ comprises the real and imaginary parts of the path loss coefficient for the $k$-th path, i.e., $\boldsymbol{\alpha}_k = [\Re\{\alpha_k\}, \Im\{\alpha_k\}]^{T}$.
To simplify the analysis, we introduce a reparameterization from $\boldsymbol{\gamma}$ to an intermediate vector $\boldsymbol{\eta} = [\boldsymbol{\tau}^{T}, \boldsymbol{\theta}^{T}, \boldsymbol{\alpha}^{T}]^{T} \in \mathbb{R}^{17}$, where $\boldsymbol{\tau} = [\tau_1, \tau_2, \tau_3, \tau_4, \tau_5]^{T}$ contains the time delays and $\boldsymbol{\theta} = [\theta_1, \theta_2]^{T}$. For the compact closed-form expressions below, we adopt a resolvable-path approximation: distinct paths are separable over the OFDM/array observation aperture, the centered subcarrier indexing above is used, and the relevant delay/gain and angle/gain score inner products vanish. Under this stated approximation,
\begin{equation}
\mathbf{J}_{\boldsymbol{\eta}} = \operatorname{blkdiag}[\mathbf{J}_\tau, \mathbf{J}_\theta, \mathbf{J}_\alpha].
\end{equation}
If these orthogonality conditions are not satisfied, the full FIM must be retained and the position EFIM is obtained directly from the Schur complement in \eqref{eq:schur_complement}. Under the adopted approximation, the required diagonal terms are:
\begin{align}
J_{\tau_{i},\tau_{i}} &= \scalebox{0.81}{$\frac{2}{\sigma^{2}}|\alpha_{i}|^{2}(2\pi \Delta f)^{2}
\mathrm{tr}\{\mathbf{G}_{i}\mathbf{R}_{x1}\mathbf{G}_{i}^{H}\}  \sum_{n=-(N_s-1)/2}^{(N_s-1)/2} n^{2}$}, \quad \scalebox{0.81}{$i=1,2,3$}
\label{eq:J-tau1} 
J_{\tau_{j},\tau_{j}} &= \scalebox{0.81}{$\frac{2}{\sigma^{2}}|\alpha_{j}|^{2}(2\pi \Delta f)^{2}
\mathrm{tr}\{\mathbf{G}_{j}\mathbf{R}_{x2}\mathbf{G}_{j}^{H}\} \sum_{n=-(N_s-1)/2}^{(N_s-1)/2} n^{2}$}, \quad \scalebox{0.81}{$j=4,5$}
\label{eq:J-tau2} 
J_{\theta_{1},\theta_{1}} &= \scalebox{0.7}{$\frac{2{N}_{s}}{\sigma^{2}} \Bigg( \sum_{k \in \{1,2,3\}} |\alpha_{k}|^{2} \, \mathrm{tr}\{\dot{\mathbf{G}}_{k,\theta_{1}} \mathbf{R}_{x1} \dot{\mathbf{G}}_{k,\theta_{1}}^{H}\} + |\alpha_{5}|^{2} \, \mathrm{tr}\{\dot{\mathbf{G}}_{5,\theta_{1}} \mathbf{R}_{x2} \dot{\mathbf{G}}_{5,\theta_{1}}^{H}\} \Bigg)$},
\label{eq:J_theta_split_simple} 
J_{\theta_{2},\theta_{2}} &= \scalebox{0.74}{$\frac{2N_s}{\sigma^{2}}\Big( |\alpha_2|^2\operatorname{tr}\{\dot{\mathbf G}_{2,\theta_2}\mathbf R_{x1}\dot{\mathbf G}_{2,\theta_2}^H\}+|\alpha_3|^2\operatorname{tr}\{\dot{\mathbf G}_{3,\theta_2}\mathbf R_{x1}\dot{\mathbf G}_{3,\theta_2}^H\}$} \nonumber
&\quad \scalebox{0.74}{$+|\alpha_4|^2\operatorname{tr}\{\dot{\mathbf G}_{4,\theta_2}\mathbf R_{x2}\dot{\mathbf G}_{4,\theta_2}^H\}+|\alpha_5|^2\operatorname{tr}\{\dot{\mathbf G}_{5,\theta_2}\mathbf R_{x2}\dot{\mathbf G}_{5,\theta_2}^H\}\Big)$},
\label{eq:J-theta2}
J_{\alpha_{i},\alpha_{i}} &= \scalebox{0.78}{$\frac{2}{\sigma^{2}}\mathrm{tr}\{\mathbf{G}_{i}\mathbf{R}_{x1}\mathbf{G}_{i}^{H}\}{N}_{s} \mathbf{I}_{2}$}, \quad \scalebox{0.81}{$i=1,2,3$}
\label{eq:J-alpha1} 
J_{\alpha_{j},\alpha_{j}} &= \scalebox{0.78}{$\frac{2}{\sigma^{2}}\mathrm{tr}\{\mathbf{G}_{j}\mathbf{R}_{x2}\mathbf{G}_{j}^{H}\}{N}_{s} \mathbf{I}_{2}$},\quad \scalebox{0.81}{$j=4,5$}
\label{eq:J-alpha2}
\end{align}
where $\mathbf{G}_i$ are the beamforming gain matrices, and $\dot{\mathbf{G}}_{i,\theta_k}$ denotes the derivative of $\mathbf{G}_i$ with respect to $\theta_k$. In particular, $\dot{\mathbf G}_{3,\theta_2}$ includes the dependence of $g$ on $\theta_5=\theta_2+\psi_0$. Under the same resolvable-path/orthogonality approximation, $J_{\theta_{1},\theta_{2}} = 0$.
To obtain the position EFIM, we must eliminate the nuisance parameters. The full FIM for $\boldsymbol{\gamma}$ is partitioned as:
\begin{equation}
\mathbf{J}_{\boldsymbol{\gamma}} = 
\begin{bmatrix}
\mathbf{J}_{pp} & \mathbf{J}_{p\alpha} 
\mathbf{J}_{\alpha p} & \mathbf{J}_{\alpha\alpha}
\end{bmatrix},
\end{equation}
where $\mathbf{J}_{pp}$ corresponds to the position parameters, $\mathbf{J}_{\alpha\alpha}$ corresponds to the path gains, and $\mathbf{J}_{p\alpha} = \mathbf{J}_{\alpha p}^T$ represents the coupling between them. The position EFIM is then obtained via the Schur complement:
\begin{equation}
\mathbf{J}_e = \scalebox{0.9}{$ \mathbf{J}_{pp} - \mathbf{J}_{p\alpha} \mathbf{J}_{\alpha\alpha}^{-1} \mathbf{J}_{\alpha p}$}.
\label{eq:schur_complement}
\end{equation}
Under the resolvable-path and score-orthogonality approximation stated above, the position--gain information block vanishes, i.e., $\mathbf{J}_{p\alpha} = \mathbf{O}$, and the Schur complement reduces to:
\begin{equation}
\mathbf{J}_e = \scalebox{0.9}{$\mathbf{J}_{pp} = \boldsymbol{\Xi}^{T} \mathbf{J}_{m} \boldsymbol{\Xi}$},
\end{equation}
where $\mathbf{J}_{\boldsymbol{m}} = \operatorname{blkdiag}[\mathbf{J}_\tau, \mathbf{J}_\theta]$ and the components $\boldsymbol{\Xi}$ and $\mathbf{T}$ (with $\mathbf{T}$ being the Jacobian transformation matrix) are defined in \eqref{eq:T}. The position-related submatrix denoted as effective FIM is given by:
\begin{equation}
\mathbf{J}_e = \scalebox{0.9}{$\boldsymbol{\Xi}^{T} \mathbf{J}_{m} \boldsymbol{\Xi}$} = 
\scalebox{0.9}{$\begin{bmatrix}
J_{1,1} & J_{1,2} 
J_{1,2} & J_{2,2}
\end{bmatrix}$}.
\label{eq:J_e_matrix}
\end{equation}
Identifiability of the target position requires $\mathbf{J}_e = \mathbf{J}_{pp} - \mathbf{J}_{p\alpha} \mathbf{J}_{\alpha\alpha}^{-1} \mathbf{J}_{\alpha p} \succ 0$. Degeneracy occurs whenever the available delay/angle score vectors fail to span both position dimensions, for example when distinct paths become locally indistinguishable or the transmit design places a sensing null toward the target. Collinearity can degrade conditioning for some geometries, but is not asserted here to be singular in every case. The CRB is well-defined for the simulated configurations for which $\mathbf J_e$ is positive definite (Fig.~\ref{fig:geometry}). Clutter can be modeled as colored noise $\mathbf{R}_n = \sigma^2 \mathbf{I} + \mathbf{R}_c$, extending the framework via $\sigma^2 \mathbf{I} \to \mathbf{R}_c + \sigma^2 \mathbf{I}$. Moreover, dynamic RCS can be addressed via chance constraints, as demonstrated in recent ISAC literature \cite{khalili2024advanced, khalili2026movable}, which enhance robustness to RCS fluctuations. These extensions are identified as future work. Finally, the CRB of target position is given by:
\begin{equation}
\begin{split}
\text{CRB} = \operatorname{tr}(\mathbf{J}_{e}^{-1}) = \frac{J_{1,1} + J_{2,2}}{J_{1,1} J_{2,2} - J_{1,2}^2}
= \frac{\mathbf{r}^H \mathbf{m} + \mathbf{m}^H \mathbf{r}}{\mathbf{r}^H \tilde{\mathbf{B}} \mathbf{r}},
\end{split}
\label{CRB-exp}
\end{equation}
where we have defined the unified vector $\mathbf{r} = [\mathbf{r}_1^T, \mathbf{r}_2^T]^T \in \mathbb{C}^{M^2+a^2}$ with $\mathbf{r}_1 \triangleq \text{vec}(\mathbf{R}_{X1})$ and $\mathbf{r}_2 \triangleq \text{vec}(\mathbf{R}_{X2})$. The parameters $\mathbf{m}$ and $\tilde{\mathbf{B}}$ are defined in \eqref{eq:ND} and \eqref{eq:CRB-end}. The details of the CRB calculation, are provided in Appendix A.
\section{Joint Beamforming and Mode Selection} \label{sec:3}
\subsection{Problem Formulation}
This paper aims to enhance target positioning accuracy while guaranteeing multi-user communication performance. We formulate an optimization problem that minimizes the CRB under strict SINR constraints, jointly optimizing the composite transmit beamforming matrix $\mathbf{F}$, the RDARS reflection matrix $\boldsymbol{\Phi}$, and the selection matrices $\mathbf{A}$ and $\mathbf{A}_{a}$. Using the SINR and CRB analyses in \eqref{eq:sinr_formula} and \eqref{CRB-exp}, the detailed optimization problem is formulated as:
\begin{subequations}
\begin{align}
 \text{(P1)} \quad & \min_{\mathbf{F},\boldsymbol{\Phi},\mathbf{r},\mathbf{A},\mathbf{A}_{a}} \quad  \scalebox{0.9}{$\frac{\mathbf{r}^H \mathbf{m} + \mathbf{m}^H \mathbf{r}}{\mathbf{r}^H \tilde{\mathbf{B}} \mathbf{r}}$} \nonumber
 \text{s.t.} \quad
 & \mathbf{r}_1 = \scalebox{0.9}{$\operatorname{vec}\left(\sum_{k=1}^K \mathbf{F}_{1,k}\right)$}, \label{eq:r1-vec}
 & \mathbf{r}_2 = \scalebox{0.9}{$\operatorname{vec}\left(\sum_{k=1}^K \mathbf{F}_{2,k}\right)$}, \label{eq:r2-vec}
 & \scalebox{0.9}{$\left| \mathbf{h}_{k}^T \begin{bmatrix} \mathbf{f}_{1,k}  \mathbf{f}_{2,k} \end{bmatrix} \right|^2 - \overline{\gamma}_{k} \sum_{i \neq k}^K \left| \mathbf{h}_{k}^T \begin{bmatrix} \mathbf{f}_{1,i}  \mathbf{f}_{2,i} \end{bmatrix} \right|^2 \geq \overline{\gamma}_{k} \sigma_{k}^2$}, \label{eq:sinr} 
 & \scalebox{0.9}{$\|\mathbf{F}\|_{F}^{2} \leq P_t$}, \label{eq:power} 
 & \scalebox{0.9}{$|\boldsymbol{\Phi}(i,i)| = 1, \quad \forall i$}, \label{eq:phi} 
 & \scalebox{0.9}{$\mathbf{A} = \mathbf{A}_{a} \mathbf{A}_{a}^{T}$}, \label{eq:A-Aa} 
 & \scalebox{0.9}{$\mathbf{A}(i,i) \in \{0, 1\}, \quad i = 1, \dots, N$}, \label{eq:A} 
 & \scalebox{0.9}{$\operatorname{tr}(\mathbf{A}) = a$}, \label{eq:a}
\end{align}
\end{subequations}
where $\mathbf{r} = [\mathbf{r}_1^T, \mathbf{r}_2^T]^T$ and $\mathbf{F} = [\mathbf{F}_1^T, \mathbf{F}_2^T]^T$.
In optimization problem (P1), constraints \eqref{eq:r1-vec} and \eqref{eq:r2-vec} represent the vectorization of the submatrices of $\mathbf{F}$. Constraint \eqref{eq:sinr} ensures that each user $k$ achieves a minimum SINR threshold $\overline{\gamma}_{k}$. Constraint \eqref{eq:power} imposes a total power budget $P_t$, while \eqref{eq:phi} enforces unit-modulus reflection coefficients. Constraints \eqref{eq:A-Aa}, \eqref{eq:A}, and \eqref{eq:a} define the feasible set for the mode selection matrices.
Problem (P1) is non-convex and challenging. To address this, we employ an AO framework that decomposes the problem into tractable sub-problems solved iteratively, integrating MM and penalty techniques. The procedure alternates between optimizing the beamforming matrix $\mathbf{F}$ with fixed $\mathbf{A}, \mathbf{A}_{a}$, and $\boldsymbol{\Phi}$, and optimizing the reflection coefficients $\boldsymbol{\Phi}$ along with the mode selection matrices $\mathbf{A}$ and $\mathbf{A}_{a}$ with fixed $\mathbf{F}$.
\subsection{Transmit Beamforming Matrix Optimization}
This section presents the proposed methodology for the joint design of beamforming, phase, and mode selection in the RDARS-aided ISAC system.
For fixed $\boldsymbol{\Phi}$, $\mathbf{A}$, and $\mathbf{A}_{a}$, the optimization problem with respect to $\mathbf{F}$ is given by
\begin{subequations}
\begin{align}
 \text{(P2)} \quad & \min_{\mathbf{F},\mathbf{r}} \quad  \frac{\mathbf{r}^H \mathbf{m} + \mathbf{m}^H \mathbf{r}}{\mathbf{r}^H \tilde{\mathbf{B}} \mathbf{r}} \nonumber
 \text{s.t.} \quad & \eqref{eq:r1-vec}, \eqref{eq:r2-vec}, \eqref{eq:sinr}, \eqref{eq:power}.
\end{align}
\end{subequations}
Let us define $\mathbf{F}_{1,k} \triangleq \mathbf{f}_{1,k} \mathbf{f}_{1,k}^H$, $\mathbf{F}_{2,k} \triangleq \mathbf{f}_{2,k} \mathbf{f}_{2,k}^H$, $\mathbf{F}_{12,k} \triangleq \mathbf{f}_{1,k} \mathbf{f}_{2,k}^H$, and $\mathbf{H}_{k} \triangleq \mathbf{h}_{k}^{*} \mathbf{h}_{k}^T$. Thus, the beamforming optimization problem (P2) can be reformulated as
\begin{subequations}
\begin{IEEEeqnarray}{l}
 \text{(P3)} \quad \min_{\substack{\mathbf{r}_1,\mathbf{r}_2, {(\mathbf{F}_{1,k})}_{k=1}^K,  {(\mathbf{F}_{2,k})}_{k=1}^K, {(\mathbf{F}_{12,k})}_{k=1}^K}} 
 \scalebox{0.9}{$\frac{\mathbf{r}^H \mathbf{m} + \mathbf{m}^H \mathbf{r}}{\mathbf{r}^H \tilde{\mathbf{B}} \mathbf{r}}$} \nonumber
 \text{s.t.} \quad \quad \quad \eqref{eq:r1-vec}, \eqref{eq:r2-vec}, \IEEEyesnumber 
 \scalebox{0.9}{$\sum_{k=1}^{K} \operatorname{tr} \left\{ \begin{bmatrix} \mathbf{F}_{1,k} & \mathbf{F}_{12,k}  \mathbf{F}_{12,k}^H & \mathbf{F}_{2,k} \end{bmatrix} \right\} \leq P_t$}, \label{eq:power-updated} 
 \scalebox{0.72}{$\displaystyle \operatorname{tr} \left\{ \mathbf{H}_k \begin{bmatrix} \mathbf{F}_{1,k} & \mathbf{F}_{12,k}  \mathbf{F}_{12,k}^H & \mathbf{F}_{2,k} \end{bmatrix} \right\} - \overline{\gamma}_{k} \sum_{{\substack{{i=1}{i\neq k}}}}^{K} \operatorname{tr} \left\{ \mathbf{H}_k \begin{bmatrix} \mathbf{F}_{1,i} & \mathbf{F}_{12,i}  \mathbf{F}_{12,i}^H & \mathbf{F}_{2,i} \end{bmatrix} \right\} \geq \overline{\gamma}_{k} \sigma_{k}^2$}.
 \label{New-SINR} 
 \IEEEyesnumber
\end{IEEEeqnarray}
\end{subequations}
To solve the non-convex problem (P3), we combine Dinkelbach's method \cite{dinkelbach1967} with a successive convex approximation of the lifted transmit-covariance problem. Define
\begin{equation}
\label{eq:Xk_definition}
\mathbf{X}_k \triangleq \begin{bmatrix}
\mathbf{F}_{1,k} & \mathbf{F}_{12,k}
\mathbf{F}_{12,k}^H & \mathbf{F}_{2,k}
\end{bmatrix}\succeq\mathbf0,\qquad \operatorname{rank}(\mathbf X_k)=1,\quad \forall k.
\end{equation}
Then,
\begin{equation}
\label{eq:r1r2_Xk}
\begin{aligned}
\mathbf r_1&=\operatorname{vec}\!\left(\sum_{k=1}^K\mathbf X_k^{(1,1)}\right),\quad
\mathbf r_2=\operatorname{vec}\!\left(\sum_{k=1}^K\mathbf X_k^{(2,2)}\right),
\mathbf r&=[\mathbf r_1^T,\mathbf r_2^T]^T.
\end{aligned}
\end{equation}
where $\mathbf X_k^{(i,j)}$ denotes the $(i,j)$-th block. Using Appendix~A, write
\begin{equation}
\label{eq:frac_obj}
f_0(\mathbf r)=\frac{N(\mathbf r)}{D(\mathbf r)},\qquad
N(\mathbf r)=\mathbf r^H\mathbf m+\mathbf m^H\mathbf r,\quad
D(\mathbf r)=\mathbf r^H\widetilde{\mathbf B}\mathbf r.
\end{equation}
On the identifiable feasible set, $D(\mathbf r)>0$. The matrix $\widetilde{\mathbf B}$ is Hermitian but is not assumed positive semidefinite. At Dinkelbach iteration $i$, we therefore solve a local convex approximation of
\begin{equation}
\label{eq:dinkelbach_sub}
\min_{\mathbf r_1,\mathbf r_2,\{\mathbf X_k\}}\;N(\mathbf r)-\varsigma^{(i)}D(\mathbf r),
\end{equation}
and update
\begin{equation}
\label{eq:varsigma_update}
\varsigma^{(i+1)}=\frac{N(\mathbf r^{(i+1)})}{D(\mathbf r^{(i+1)})}.
\end{equation}
Let $\widetilde{\mathbf B}=\mathbf B_+-\mathbf B_-$ be its spectral decomposition into positive and negative semidefinite parts, with $\mathbf B_+,\mathbf B_-\succeq\mathbf0$. At the current iterate $\mathbf r^{(t)}$, the concave term is majorized as
\begin{equation}
-\varsigma^{(i)}\mathbf r^H\mathbf B_+\mathbf r
\le -2\varsigma^{(i)}\Re\{\mathbf r^H\mathbf B_+\mathbf r^{(t)}\}+\mathrm{const}.
\label{eq:D_lower_bound}
\end{equation}
After dropping constants, the resulting convex subproblem is
\begin{subequations}
\label{eq:convex_P4}
\begin{IEEEeqnarray}{l}
\text{(P4)}\quad \min_{\mathbf r_1,\mathbf r_2,\{\mathbf X_k\}}
\;2\Re\{\mathbf m^H\mathbf r\}
-2\varsigma^{(i)}\Re\{\mathbf r^H\mathbf B_+\mathbf r^{(t)}\}\nonumber
\hspace{24mm}+\varsigma^{(i)}\mathbf r^H\mathbf B_-\mathbf r \nonumber
\text{s.t.}\quad \eqref{eq:r1r2_Xk},\;\eqref{New-SINR},\quad
\mathbf X_k\succeq\mathbf0,\ \forall k, \nonumber
\hspace{12mm}\sum_{k=1}^K\operatorname{tr}(\mathbf X_k)\le P_t.
\end{IEEEeqnarray}
\end{subequations}
Problem (P4) is solved with a standard convex solver such as CVX \cite{cvx2016} after dropping the rank-one constraints in \eqref{eq:Xk_definition}; hence, it is an SDR of (P3). If the relaxed solution is rank one, the beamformers follow directly by factorization. Otherwise, a standard Gaussian-randomization/rank-one recovery followed by SINR-feasibility power rescaling is used, and the feasible candidate with the smallest original CRB is retained. Accordingly, this transmit update is relaxation based and no global-optimality claim is made.
\subsection{Reflection Matrix and Selection Matrices Optimization}
Variables \(\boldsymbol{\Phi}\), \(\mathbf{A}\) and \(\mathbf{A}_{a}\) share diagonal structures with unit-modulus properties: \((\text{diag}(\boldsymbol{\Phi}))^{H}\text{diag}(\boldsymbol{\Phi}) = N\), \((\text{diag}(\mathbf{A}))^{T}\text{diag}(\mathbf{A}) = a\), and \((\text{vec}(\mathbf{A}_{a}))^{T}\text{vec}(\mathbf{A}_{a}) = a\). Thus, we optimize them jointly. Given fixed \(\mathbf{F}_1\) and \(\mathbf{F}_2\), the corresponding sub-problem is given by:
\begin{subequations}
\begin{align}
 \text{(P5)} \quad & \min_{\boldsymbol{\Phi},\mathbf{A},\mathbf{A}_{a}} \quad \text{CRB} \nonumber 
 & \text{s.t.} \quad \eqref{eq:sinr}, \eqref{eq:phi}, \eqref{eq:A-Aa}, \eqref{eq:A}, \eqref{eq:a}.
\end{align}
\end{subequations}
To handle the coupled constraints \eqref{eq:sinr} and \eqref{eq:A-Aa}, we employ the penalty method. Introduce auxiliary variables \(s_{k,i}\) such that:
\begin{align}
 & \scalebox{0.9}{$\frac{|s_{k,k}|^{2}}{\sum_{i \neq k}^{K} |s_{k,i}|^{2} + \sigma_{k}^{2}} \geq \overline{\gamma}_{k}$}, \quad \forall k = 1,\dots,K. \label{eq:Sk1} 
 & \scalebox{0.9}{$\mathbf{h}_{k}^{T} \mathbf{f}_{i} = s_{k,i}$}, \quad \forall k, \forall i. \label{eq:Sk2}
\end{align}
Incorporating \eqref{eq:A-Aa} and \eqref{eq:Sk2} as penalty terms yields:
\begin{subequations}
\begin{align}
 \text{(P6)} \quad & \min_{\boldsymbol{\Phi},\mathbf{A},\mathbf{A}_{a},s_{k,i}} \quad \scalebox{0.9}{$\text{CRB} +\frac{1}{2\rho_{1}} \sum_{k=1}^{K} \sum_{i=1}^{K} |\mathbf{h}_{k}^{T} \mathbf{f}_{i} - s_{k,i}|^{2}$} \nonumber 
 & \quad \quad \quad \quad \scalebox{0.9}{$+ \frac{1}{2\rho_{2}} \|\mathbf{A} - \mathbf{A}_{a} \mathbf{A}_{a}^{T}\|_{F}^{2}$} \label{eq:20a} \nonumber 
 & \text{s.t.}
 \quad \eqref{eq:phi}, \eqref{eq:A},\eqref{eq:a},  \eqref{eq:Sk1}, 
\end{align}
\end{subequations}
where $\rho_{1}$ and $\rho_{2}$ are penalty coefficients. Problem (P6) is still non-convex, but the constraints are now decoupled across variables. To solve Problem (P6), we iteratively update the following four blocks.
\subsubsection{Update \(s_{k,i}\)}
\label{subsubsec:update_s}
With fixed \(\boldsymbol{\Phi}\), \(\mathbf{A}\), and \(\mathbf{A}_{a}\), the sub-problem for \(s_{k,i}\) is given by:
\begin{subequations}
\begin{align}
 \text{(P7)} \quad & \min_{s_{k,i}} \quad \scalebox{0.9}{$\sum_{k=1}^{K} \sum_{i=1}^{K} |\mathbf{h}_{k}^{T} \mathbf{f}_{i} - s_{k,i}|^{2}$} \nonumber 
 & \text{s.t.} \quad \eqref{eq:Sk1}.
\end{align}
\end{subequations}
The objective consists of \(K\) independent terms, and for each \(k\) the variables \(\{s_{k,i}, \forall i\}\) are separable. Hence, \(K\) sub-problems can be solved independently. The \(k\)-th sub-problem is:
\begin{subequations}
\begin{align}
 \text{(P8)} \quad & \min_{s_{k,i}} \quad \scalebox{0.9}{$\sum_{i=1}^{K} |\mathbf{h}_{k}^{T} \mathbf{f}_{i} - s_{k,i}|^{2}$} \label{eq:23a} \nonumber 
 & \text{s.t.}  \quad \eqref{eq:Sk1}.
\end{align}
\end{subequations}
Problem (P8) is a quadratically constrained quadratic program. Strong duality holds when Slater's condition is satisfied, enabling the use of the Lagrangian dual method \cite{boyd2004convex}. Introducing the dual variable \(\mu_k \ge 0\), the Lagrangian is:
\begin{align}
 \mathcal{L}(s_{k,i},\mu_k) = & \scalebox{0.9}{$\sum_{i=1}^K |\mathbf{h}_{k}^T \mathbf{f}_i - s_{k,i}|^2$} \nonumber 
 & \scalebox{0.9}{$+ \mu_k \left( \overline{\gamma}_k \left( \sum_{i \neq k}^{K} |s_{k,i}|^2 + \sigma_{k}^2 \right) - |s_{k,k}|^2 \right)$}. \label{eq:lagrangian}
\end{align}
The dual function is:
\begin{equation}
\scalebox{0.9}{$f_{\text{dual}}(\mu_k) = \min_{s_{k,i}} L(s_{k,i},\mu_k)$}.
\end{equation}
For \(f_{\text{dual}}(\mu_k)\) to be bounded, \(\mu_k\) must satisfy \(0 \le \mu_k < 1\). The proof is omitted for simplicity. Setting the first-order derivative to zero yields the optimal value of $s_{k,i}$ is:
\begin{equation}
s_{k,i}^{\star}=
\scalebox{0.9}{$\begin{cases}
\dfrac{\mathbf{h}_{k}^{T} \mathbf{f}_i}{1+\mu_k \overline{\gamma}_k}, & i\neq k,[0.3em]
\dfrac{\mathbf{h}_{k}^{T} \mathbf{f}_k}{1-\mu_k}, & i=k,
\end{cases}$}
\label{eq:opt_ski}
\end{equation}
where \(\mu_k\) is determined to satisfy the complementary slackness condition:
\begin{equation}
\scalebox{0.9}{$\mu_k\!\left( \overline{\gamma}_k\!\left(\sum_{i\neq k} |s_{k,i}^{\star}(\mu_k)|^2 + \sigma_{k}^2 \right) - |s_{k,k}^{\star}(\mu_k)|^2 \right)=0$}.
\end{equation}
This can be efficiently found via a one-dimensional search technique.
\subsubsection{Update $\boldsymbol{\phi}$}
\label{subsubsec:update_phi}
With $s_{k,i}$, $\mathbf A$, and $\mathbf A_a$ fixed, we use the equality penalty already introduced in (P6), rather than introducing a second SINR-violation penalty. Partition $\mathbf f_i=[\mathbf f_{1,i}^T,\mathbf f_{2,i}^T]^T$ and define
\begin{align}
c_{k,i}&\triangleq\mathbf h_{bu,k}^T\mathbf f_{1,i}+\mathbf h_{ru,k}^T\mathbf A_a\mathbf f_{2,i},
\mathbf b_{k,i}&\triangleq\operatorname{diag}(\mathbf H_{br}\mathbf f_{1,i})(\mathbf I-\mathbf A)\mathbf h_{ru,k}.
\end{align}
Then $\mathbf h_k^T\mathbf f_i=c_{k,i}+\boldsymbol\phi^T\mathbf b_{k,i}$, and the phase-update subproblem is
\begin{subequations}
\begin{align}
\text{(P9)}\quad \min_{\boldsymbol\phi}\;&\operatorname{CRB}(\boldsymbol\phi)+\frac{1}{2\rho_1}\sum_{k=1}^{K}\sum_{i=1}^{K}|\boldsymbol\phi^T\mathbf b_{k,i}+c_{k,i}-s_{k,i}|^2\nonumber
\text{s.t.}\;&|\phi_n|=1,\quad \forall n.
\end{align}
\end{subequations}
For fixed $\mathbf A$ and $\mathbf A_a$, only $\mathbf G_3$ depends on $\boldsymbol\phi$. Because both $g$ and its $\theta_2$-derivative enter the corrected FIM, Appendix~B writes $\operatorname{CRB}(\boldsymbol\phi)=F(S_0(\boldsymbol\phi),S_1(\boldsymbol\phi))$, where $S_0=|g|^2=\boldsymbol\phi^H\mathbf Q_0\boldsymbol\phi$ and $S_1=|\partial g/\partial\theta_2|^2=\boldsymbol\phi^H\mathbf Q_1\boldsymbol\phi$. Moreover, the communication penalty can be written as $\boldsymbol\phi^H\mathbf Q_c\boldsymbol\phi+2\Re\{\boldsymbol\phi^H\mathbf q_c\}+\mathrm{const}$, where
\begin{equation}
\mathbf Q_c=\sum_{k,i}\mathbf b_{k,i}^{*}\mathbf b_{k,i}^{T},\qquad
\mathbf q_c=\sum_{k,i}\mathbf b_{k,i}^{*}(c_{k,i}-s_{k,i}).
\end{equation}
At iteration $t$, we use the local first-order SCA model of $F(S_0,S_1)$ at $(s_{0,t},s_{1,t})$, with $\mu_{q,t}=\partial F/\partial S_q$, $q\in\{0,1\}$. This gives the local quadratic problem
\begin{subequations}
\begin{align}
\text{(P10)}\quad \min_{\boldsymbol\phi}\;&\boldsymbol\phi^H\mathbf S_t\boldsymbol\phi+2\Re\{\boldsymbol\phi^H\mathbf v_t\}\nonumber
\text{s.t.}\;&|\phi_n|=1,\quad \forall n,
\end{align}
\end{subequations}
where $\mathbf S_t=\mu_{0,t}\mathbf Q_0+\mu_{1,t}\mathbf Q_1+(2\rho_1)^{-1}\mathbf Q_c$ and $\mathbf v_t=(2\rho_1)^{-1}\mathbf q_c$. With $\mathbf M_t=\lambda_{\max}(\mathbf S_t)\mathbf I$, unimodular quadratic majorization \cite{Sun2017} yields the candidate
\begin{equation}
\boldsymbol\phi^{\rm c}=-\exp\!\left(j\arg\left((\mathbf S_t-\mathbf M_t)\boldsymbol\phi^{(t)}+\mathbf v_t\right)\right).
\label{eq:phi-opt}
\end{equation}
Since the first-order CRB model is local rather than a global upper bound, the candidate is accepted only if it does not increase the original fixed-$\rho_1$ objective in (P9); otherwise the current phase vector is retained.
\subsubsection{Update of $\mathbf a$}
Let $\mathbf a=[a_1,\ldots,a_N]^T$ and $\mathbf A=\operatorname{diag}(\mathbf a)$. With $\boldsymbol\phi$, $s_{k,i}$, and $\mathbf A_a$ fixed, the block subproblem consistent with (P6) is
\begin{subequations}
\begin{align}
\text{(P11)}\quad \min_{\mathbf a}\;&\operatorname{CRB}(\mathbf a)+\frac{1}{2\rho_1}\sum_{k,i}|\mathbf h_k^T\mathbf f_i-s_{k,i}|^2\nonumber
&+\frac{1}{2\rho_2}\|\mathbf A-\mathbf A_a\mathbf A_a^T\|_F^2\nonumber
\text{s.t.}\;&a_n\in\{0,1\},\quad \mathbf1^T\mathbf a=a.
\end{align}
\end{subequations}
For Path~3, define $g_0\triangleq\mathbf c^H(\theta_4)\boldsymbol\Phi\mathbf c(\theta_5)$ and $\mathbf v\triangleq\overline{\mathbf c(\theta_4)}\odot\boldsymbol\phi\odot\mathbf c(\theta_5)$, so that $g=g_0-\mathbf a^T\mathbf v$. Likewise, with $\dot{\mathbf c}(\theta_5)=\partial\mathbf c(\theta_5)/\partial\theta_2$, we have $\partial g/\partial\theta_2=\dot g_0-\mathbf a^T\dot{\mathbf v}$, where $\dot g_0\triangleq\mathbf c^H(\theta_4)\boldsymbol\Phi\dot{\mathbf c}(\theta_5)$ and $\dot{\mathbf v}\triangleq\overline{\mathbf c(\theta_4)}\odot\boldsymbol\phi\odot\dot{\mathbf c}(\theta_5)$. Hence the Path-3 information is quadratic in the binary vector $\mathbf a$.
For the communication penalty, define
\begin{align}
\mathbf t_{k,i}&\triangleq-\operatorname{diag}(\mathbf h_{ru,k})\boldsymbol\Phi\mathbf H_{br}\mathbf f_{1,i},
d_{k,i}&\triangleq\mathbf h_{bu,k}^T\mathbf f_{1,i}+\mathbf h_{ru,k}^T\boldsymbol\Phi\mathbf H_{br}\mathbf f_{1,i}+\mathbf h_{ru,k}^T\mathbf A_a\mathbf f_{2,i},
\end{align}
so that $\mathbf h_k^T\mathbf f_i=\mathbf a^T\mathbf t_{k,i}+d_{k,i}$. After the same local first-order approximation of the CRB, collect the resulting quadratic terms as
\begin{equation}
G(\mathbf a|\mathbf a^{(t)})=\mathbf a^T\mathbf S_t\mathbf a+2\Re\{\mathbf a^T\mathbf v_t\}+\mathrm{const}.
\label{G(a)}
\end{equation}
Because $\mathbf a^T\mathbf a=a$ is fixed, with $\lambda_t=\lambda_{\max}(\mathbf S_t)$ the quadratic term is majorized by
\begin{equation}
\mathbf a^T\mathbf S_t\mathbf a\le2\Re\{\mathbf a^T(\mathbf S_t-\lambda_t\mathbf I)\mathbf a^{(t)}\}+\mathrm{const}.
\label{eq:linear_majorant}
\end{equation}
Thus, defining $\mathbf e=2\Re\{(\mathbf S_t-\lambda_t\mathbf I)\mathbf a^{(t)}+\mathbf v_t\}$, the local binary problem is
\begin{subequations}
\begin{align}
\text{(P12)}\quad \min_{\mathbf a}\;&\mathbf a^T\mathbf e\nonumber
\text{s.t.}\;&a_n\in\{0,1\},\quad \mathbf1^T\mathbf a=a.
\end{align}
\end{subequations}
Its solution selects the $a$ smallest entries of $\mathbf e$. If $\mathcal L$ is their index set,
\begin{equation}
\mathbf a^{\rm c}(n)=\begin{cases}1,&n\in\mathcal L,0,&\text{otherwise}.
\end{cases}
\label{eq:A-opt}
\end{equation}
The candidate is accepted only if the original fixed-penalty objective decreases; otherwise the current selection is retained.
\begin{algorithm}
\caption{CRB Optimization for Joint Beamforming and Mode Selection in RDARS-aided ISAC.}
\label{alg:main}
\begin{algorithmic}[1]
\REQUIRE $\mathbf h_{bu,k}$, $\mathbf h_{ru,k}$, $P_t$, $\sigma_k^2$, $\overline\gamma_k$, $\rho_1$, $\rho_2$, and $0<c_1,c_2<1$.
\STATE Initialize $\boldsymbol\Phi^0$, $\mathbf F^0$, $\mathbf A^0$, and $\mathbf A_a^0$.
\REPEAT
\STATE Update $\mathbf F$ by solving relaxed (P4), with rank-one recovery if required.
\STATE Update $s_{k,i}$ based on \eqref{eq:opt_ski}.
\STATE Update $\boldsymbol\phi$ from \eqref{eq:phi-opt} with the fixed-penalty acceptance check.
\STATE Update $\mathbf A$ from \eqref{eq:A-opt} with the fixed-penalty acceptance check.
\STATE Update $\mathbf A_a$ by solving (P13).
\STATE $\rho_1\gets c_1\rho_1$, $\rho_2\gets c_2\rho_2$.
\UNTIL{the stopping criterion is satisfied.}
\ENSURE $\mathbf F^*$, $\boldsymbol\Phi^*$, $\mathbf A^*$, $\mathbf A_a^*$.
\end{algorithmic}
\end{algorithm}
