\section{Calculation of the FIM}
\label{app:A}
Based on the complex Gaussian distribution of the received signal in \eqref{eq:radar_signal}, the elements of $\mathbf{J}_{\boldsymbol{\eta}}$ are given by \cite{kay1993fundamentals}:
\begin{align}
\mathbf{J}_{\bm{\eta}} &= 
\scalebox{0.9}{$\begin{bmatrix} 
\mathbf{J}_{\bm{\tau},\bm{\tau}} & \mathbf{J}_{\bm{\tau},\bm{\theta}} & \mathbf{J}_{\bm{\tau},\bm{\alpha}}  
\mathbf{J}_{\bm{\theta},\bm{\tau}} & \mathbf{J}_{\bm{\theta},\bm{\theta}} & \mathbf{J}_{\bm{\theta},\bm{\alpha}}  
\mathbf{J}_{\bm{\alpha},\bm{\tau}} & \mathbf{J}_{\bm{\alpha},\bm{\theta}} & \mathbf{J}_{\bm{\alpha},\bm{\alpha}}
\end{bmatrix}$}, 
\mathbf{J}^{(\textit{i},\textit{j})}_{\bm{\eta}} &= \scalebox{0.9}{$\frac{2}{\sigma^2}\sum_{n=-\frac{N_s-1}{2}}^{\frac{N_s-1}{2}} \Re\left\{
\frac{\partial \bm{\mu}^H[n]}{\partial \eta_{i,j}}
\frac{\partial \bm{\mu}[n]}{\partial \eta_{i,j}} \right\}$}. \label{S.B}
\end{align}
The FIM elements are derived from the partial derivatives of the signal model. The derivatives with respect to delays $\tau_i$ are:
\begin{align}
\frac{\partial \bm{\mu}[n]}{\partial \tau_{1}} &= 
\scalebox{0.9}{$\begin{bmatrix}
\alpha_{1}e^{-j2\pi n \Delta f\tau_{1}}[\mathbf{G}_{1},0]\mathbf{X}[n](-j2\pi n \Delta f) 
\bm{0}
\end{bmatrix}$}, \label{p.d1}
\frac{\partial \bm{\mu}[n]}{\partial \tau_{2}} &= 
\scalebox{0.9}{$\begin{bmatrix}
\bm{0} 
\alpha_{2}e^{-j2\pi n \Delta f\tau_{2}}[\mathbf{G}_{2},0]\mathbf{X}[n](-j2\pi n \Delta f)
\end{bmatrix}$},
\end{align}
Analogous expressions can be derived for $\tau_3$, $\tau_4$ and $\tau_5$. The derivatives with respect to delays angles $\theta_i$ and path losses $\alpha_i$ are given by:
\begin{align}
\frac{\partial \bm{\mu}[n]}{\partial \theta_{1}} &= 
\scalebox{0.85}{$\begin{bmatrix}
\alpha_{1}e^{-j2\pi n \Delta f\tau_{1}}[\dot{\mathbf{G}}_{1},0]\mathbf{X}[n] 
+\alpha_{3}e^{-j2\pi n \Delta f\tau_{3}}[\dot{\mathbf{G}}_{3},0]\mathbf{X}[n] 
+\alpha_{5}e^{-j2\pi n \Delta f\tau_{5}}[0,\dot{\mathbf{G}}_{5}]\mathbf{X}[n] 
\alpha_{2}e^{-j2\pi n \Delta f\tau_{2}}[\dot{\mathbf{G}}_{2},0]\mathbf{X}[n]
\end{bmatrix}$}, \label{eq:partial_theta1} 
\frac{\partial \bm{\mu}[n]}{\partial \theta_{2}} &=
\scalebox{0.82}{$\begin{bmatrix}
\alpha_{3}e^{-j2\pi n \Delta f\tau_{3}}[\dot{\mathbf{G}}_{3,\theta_2},0]\mathbf{X}[n]
+\alpha_{5}e^{-j2\pi n \Delta f\tau_{5}}[0,\dot{\mathbf{G}}_{5,\theta_2}]\mathbf{X}[n] 
\alpha_{2}e^{-j2\pi n \Delta f\tau_{2}}[\dot{\mathbf{G}}_{2,\theta_2},0]\mathbf{X}[n]
+\alpha_{4}e^{-j2\pi n \Delta f\tau_{4}}[0,\dot{\mathbf{G}}_{4,\theta_2}]\mathbf{X}[n]
\end{bmatrix}$}, \label{eq:partial_theta2} 
\frac{\partial \bm{\mu}[n]}{\partial \alpha_{i}^{R}} &= -j \frac{\partial \bm{\mu}[n]}{\partial \alpha_{i}^{I}} =
\scalebox{0.86}{$\begin{bmatrix}
e^{-j2\pi n \Delta f\tau_{i}}[\mathbf{G}_{i},0]\mathbf{X}[n] 
\bm{0}
\end{bmatrix}$}. \label{eq:partial_alpha}
\end{align}
Under the resolvable-path/score-orthogonality approximation stated in Section III, the FIM reduces to $\mathbf{J}_{\boldsymbol{\eta}} = \operatorname{blkdiag}[\mathbf{J}_\tau, \mathbf{J}_\theta, \mathbf{J}_\alpha]$. By substituting the partial derivatives \eqref{p.d1}-\eqref{eq:partial_alpha} into the Slepian-Bangs \eqref{S.B}, the diagonal elements of the FIM are obtained as \eqref{eq:J-tau1}-\eqref{eq:J-alpha2}.
The transformation matrix $\mathbf{T}$ is defined as the Jacobian of $\bm{\eta}$ with respect to $\bm{\gamma}$ and can be obtained as:
\begin{equation}
\mathbf{T} \triangleq \frac{\partial \eta}{\partial \gamma} = 
\begin{bmatrix}
\boldsymbol{\Xi} & \mathbf{O} 
\mathbf{O} & \mathbf{I}_{10}
\end{bmatrix},
\label{eq:T}
\end{equation}
where $\boldsymbol{\Xi} = [{\nabla}_{\bm{\tau},\mathbf{p}}^{T}, {\nabla}_{\bm{\theta},\mathbf{p}}^{T}]^{T}$. Considering the five paths introduced in \eqref{eq:radar_signal} and definition of the parameters $\mathbf{e}_1 = \frac{(\mathbf{p} - \mathbf{q})^T}{\|\mathbf{p} - \mathbf{q}\|}, \quad
\mathbf{e}_2 = \frac{(\mathbf{p} - \mathbf{r})^T}{\|\mathbf{p} - \mathbf{r}\|}$, the gradient expressions with respect to the position $\mathbf{p}$ are given by:
\begin{align}
\nabla_{\tau_1,p} &= \scalebox{0.9}{$\frac{2}{c} \mathbf{e}_{1}$}, 
\nabla_{\tau_2,p} &= \nabla_{\tau_3,p} = \nabla_{\tau_5,p} = \scalebox{0.9}{$\frac{1}{c} [\mathbf{e}_{1} + \mathbf{e}_{2}]$},
\nabla_{\tau_4,p} &= \scalebox{0.9}{$\frac{2}{c} \mathbf{e}_{2}$}.
\end{align}
where parameter $c$ denotes the speed of light in vacuum. The angles $\theta_1$ and $\theta_2$ are computed as: $\theta_1 = \tan^{-1} \left( \frac{y_p - y_q}{x_p - x_q} \right)$ and $\theta_2 = \tan^{-1} \left( \frac{y_p - y_r}{x_p - x_r} \right)$. Thus, the gradient vectors are given by:
\begin{align}
\begin{split}
\nabla_{\theta_{1},\mathbf{p}} &= \scalebox{0.9}{$\left[\frac{y_q - y_p}{(x_p - x_q)^2 + (y_p - y_q)^2},\frac{x_p - x_q}{(x_p - x_q)^2 + (y_p - y_q)^2}\right]$} 
&= \scalebox{0.9}{$\frac{1}{\|\mathbf{p} - \mathbf{q}\|}\left[-\sin\theta_1,\cos\theta_1\right]$}
=\scalebox{0.9}{$\boldsymbol{\rho}_1^T$},
\end{split}
\label{eq:grad1} 
\begin{split}
\nabla_{\theta_2,\mathbf{p}}
&= \scalebox{0.9}{$\frac{1}{\|\mathbf{r} - \mathbf{p}\|}\left[-\sin\theta_2,\cos\theta_2\right]$}=
\scalebox{0.9}{$\boldsymbol{\rho}_2^T$}.
\end{split}
\label{eq:grad2}
\end{align}
Therefore, the FIM for $\bm{\gamma}$ is given by:
\begin{equation}
\mathbf{J}_{\bm{\gamma}} = \mathbf{T}^{T}\, \mathbf{J}_{\bm{\eta}} \, \mathbf{T}
=\scalebox{0.9}{$\begin{bmatrix}
\boldsymbol{\Xi}  & \mathbf{O} 
\mathbf{O} & \mathbf{I}
\end{bmatrix} ^{T}
\mathbf{J}_{\bm{\eta}}
\begin{bmatrix}
\boldsymbol{\Xi}  & \mathbf{O} 
\mathbf{O} & \mathbf{I}
\end{bmatrix}$}
=\scalebox{0.9}{$\begin{bmatrix}
\boldsymbol{\Xi}^{T} \mathbf{J}_{m} \boldsymbol{\Xi}  & \mathbf{O} 
\mathbf{O} & \mathbf{J}_{\bm{\alpha}}
\end{bmatrix}$},
\end{equation}
where $\mathbf{J}_{\boldsymbol{m}} = \operatorname{blkdiag}[\mathbf{J}_\tau, \mathbf{J}_\theta]$. 
We can also obtain:
\begin{align}
\boldsymbol{\Xi} &= \scalebox{0.9}{$\left[ 2c^{-1}\mathbf{e}_1, c^{-1}\mathbf{e}_1 + c^{-1}\mathbf{e}_2, c^{-1}\mathbf{e}_1 + c^{-1}\mathbf{e}_2, \right.$} \nonumber 
&\quad \scalebox{0.9}{$\left. 2c^{-1}\mathbf{e}_2, c^{-1}\mathbf{e}_1 + c^{-1}\mathbf{e}_2, \boldsymbol{\rho}_1, \boldsymbol{\rho}_2 \right]^{T}$}.
\end{align}
Therefore, the position-related submatrix denoted as effective FIM is derived as follows:
\begin{align}
\mathbf{J}_{e_{2\times 2}} &= \bm{\Xi}^{T}\mathbf{J}_{m}\bm{\Xi} \nonumber 
&= \scalebox{0.9}{$J_{\tau_{1}\tau_{1}}\frac{4}{c^{2}}\mathbf{e}_{1}\mathbf{e}_{1}^{T}+J_{\tau_{2}\tau_{2}}\frac{1}{c^{2}}[\mathbf{e}_{1}+\mathbf{e}_{2}][\mathbf{e}_{1}+\mathbf{e}_{2}]^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+ J_{\tau_{3}\tau_{3}}\frac{1}{c^{2}}[\mathbf{e}_{1}+\mathbf{e}_{2}][\mathbf{e}_{1}+\mathbf{e}_{2}]^{T}+J_{\tau_{4}\tau_{4}}\frac{4}{c^{2}}\mathbf{e}_{2}\mathbf{e}_{2}^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+ J_{\tau_{5}\tau_{5}}\frac{1}{c^{2}}[\mathbf{e}_{1}+\mathbf{e}_{2}][\mathbf{e}_{1}+\mathbf{e}_{2}]^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+ J_{\theta_{1}\theta_{1}}\boldsymbol{\rho}_{1}\boldsymbol{\rho}_{1}^{T}+J_{\theta_{2}\theta_{2}}\boldsymbol{\rho}_{2}\boldsymbol{\rho}_{2}^{T}$}.
\end{align}
Substituting the individual FIM elements, we can obtain:
\begin{subequations}
\begin{align}
\mathbf{J}_{e} &= \scalebox{0.9}{$\frac{2N_s(N_s^{2}-1)}{12\sigma^{2}c^{2}}(2\pi\Delta f)^{2}$} \times \nonumber 
&\quad \scalebox{0.9}{$\Bigg[ |\alpha_{1}|^{2}\mathrm{tr}(\mathbf{G}_{1}\mathbf{R}_{X1}\mathbf{G}_{1}^{H})4\mathbf{e}_{1}\mathbf{e}_{1}^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+ |\alpha_{2}|^{2}\mathrm{tr}(\mathbf{G}_{2}\mathbf{R}_{X1}\mathbf{G}_{2}^{H})(\mathbf{e}_{1}+\mathbf{e}_{2})(\mathbf{e}_{1}+\mathbf{e}_{2})^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+ |\alpha_{3}|^{2}\mathrm{tr}(\mathbf{G}_{3}\mathbf{R}_{X1}\mathbf{G}_{3}^{H})(\mathbf{e}_{1}+\mathbf{e}_{2})(\mathbf{e}_{1}+\mathbf{e}_{2})^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+ 4|\alpha_{4}|^{2}\mathrm{tr}(\mathbf{G}_{4}\mathbf{R}_{X2}\mathbf{G}_{4}^{H})\mathbf{e}_{2}\mathbf{e}_{2}^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+ |\alpha_{5}|^{2}\mathrm{tr}(\mathbf{G}_{5}\mathbf{R}_{X2}\mathbf{G}_{5}^{H})(\mathbf{e}_{1}+\mathbf{e}_{2})(\mathbf{e}_{1}+\mathbf{e}_{2})^{T} \Bigg]$} \nonumber 
&\quad + \scalebox{0.9}{$\Bigg[ \frac{2}{\sigma^{2}}|\alpha_{1}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{1,\theta_{1}}\mathbf{R}_{X1}\dot{\mathbf{G}}_{1,\theta_{1}}^{H}\}N_s$} \nonumber 
&\quad \scalebox{0.9}{$+ \frac{2}{\sigma^{2}}|\alpha_{3}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{3,\theta_{1}}\mathbf{R}_{X1}\dot{\mathbf{G}}_{3,\theta_{1}}^{H}\}N_s$} \nonumber 
&\quad \scalebox{0.9}{$+ \frac{2}{\sigma^{2}}|\alpha_{5}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{5,\theta_{1}}\mathbf{R}_{X2}\dot{\mathbf{G}}_{5,\theta_{1}}^{H}\}N_s$} \nonumber 
\end{align}
\begin{align}
&\quad \scalebox{0.9}{$+ \frac{2}{\sigma^{2}}|\alpha_{2}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{2,\theta_{1}}\mathbf{R}_{X1}\dot{\mathbf{G}}_{2,\theta_{1}}^{H}\}N_s\Bigg]\boldsymbol{\rho}_{1}\boldsymbol{\rho}_{1}^{T}$} \nonumber 
&\quad + \scalebox{0.9}{$\Bigg[ \frac{2}{\sigma^{2}}|\alpha_{5}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{5,\theta_{2}}\mathbf{R}_{X2}\dot{\mathbf{G}}_{5,\theta_{2}}^{H}\}N_s$} \nonumber 
&\quad \scalebox{0.9}{$+ \frac{2}{\sigma^{2}}|\alpha_{2}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{2,\theta_{2}}\mathbf{R}_{X1}\dot{\mathbf{G}}_{2,\theta_{2}}^{H}\}N_s$} \nonumber 
&\quad \scalebox{0.9}{$+ \frac{2}{\sigma^{2}}|\alpha_{3}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{3,\theta_{2}}\mathbf{R}_{X1}\dot{\mathbf{G}}_{3,\theta_{2}}^{H}\}N_s$} \nonumber 
&\quad \scalebox{0.9}{$+ \frac{2}{\sigma^{2}}|\alpha_{4}|^{2}\mathrm{tr}\{\dot{\mathbf{G}}_{4,\theta_{2}}\mathbf{R}_{X2}\dot{\mathbf{G}}_{4,\theta_{2}}^{H}\}N_s\Bigg]\boldsymbol{\rho}_{2}\boldsymbol{\rho}_{2}^{T}$}. \label{eq:Je_final}
\end{align}
\end{subequations}
Then, we define new parameters as follows:
\begin{align}
\lambda_{k} &\triangleq \scalebox{0.9}{$\frac{2\pi^{2}N_s(N_s^{2}-1)(\Delta f)^{2}}{3\sigma^{2}c^{2}}|\alpha_{k}|^{2}l_{k}$}, \qquad \scalebox{0.9}{$k=1,2,\ldots,5$} \label{eq:lambda}
\end{align}
where $l_1 = 4\operatorname{tr}\{\mathbf{G}_1 \mathbf{R}_{x1} \mathbf{G}_1^{H}\}$, $l_2 = \operatorname{tr}\{\mathbf{G}_2 \mathbf{R}_{x1} \mathbf{G}_2^{H}\}$, $l_3 = \operatorname{tr}\{\mathbf{G}_3 \mathbf{R}_{x1} \mathbf{G}_3^{H}\}$, $l_4 = 4\operatorname{tr}\{\mathbf{G}_4 \mathbf{R}_{x2} \mathbf{G}_4^{H}\}$ and $l_5 = \operatorname{tr}\{\mathbf{G}_5 \mathbf{R}_{x2} \mathbf{G}_5^{H}\}$.
\begin{align}
\delta_{k} &\triangleq \scalebox{0.9}{$\frac{2}{\sigma^{2}}N_s|\alpha_{k}|^{2}m_{k}$}, \quad \scalebox{0.9}{$k=1,2,3,5$}. 
\end{align}
where $m_k = \operatorname{tr}\{\dot{\mathbf{G}}_{k,\theta_1} \mathbf{R}_x^{(k)} \dot{\mathbf{G}}_{k,\theta_1}^{H}\}$, with $\mathbf{R}_x^{(k)} = \mathbf{R}_{x1}$ for $k \in \{1,2,3\}$ and $\mathbf{R}_x^{(k)} = \mathbf{R}_{x2}$ for $k = 5$.
\begin{align}
\eta_{k}  &\triangleq \scalebox{0.9}{$\frac{2}{\sigma^{2}}N_s|\alpha_{k}|^{2}n_{k}$}, \quad \scalebox{0.9}{$k=2,3,4,5$} 
\end{align}
where
$n_{2} = \mathrm{tr}\{\dot{\mathbf{G}}_{2,\theta_{2}}\mathbf{R}_{x1}\dot{\mathbf{G}}_{2,\theta_{2}}^{H}\},$
$n_{3} = \mathrm{tr}\{\dot{\mathbf{G}}_{3,\theta_{2}}\mathbf{R}_{x1}\dot{\mathbf{G}}_{3,\theta_{2}}^{H}\},$
$n_{4} = \mathrm{tr}\{\dot{\mathbf{G}}_{4,\theta_{2}}\mathbf{R}_{x2}\dot{\mathbf{G}}_{4,\theta_{2}}^{H}\}$ and
$n_{5} = \mathrm{tr}\{\dot{\mathbf{G}}_{5,\theta_{2}}\mathbf{R}_{x2}\dot{\mathbf{G}}_{5,\theta_{2}}^{H}\}$. Thus, the equivalent FIM is:
\begin{align}
\mathbf{J}_{e} &= \scalebox{0.9}{$(\lambda_{1}+\lambda_{2}+\lambda_{3}+\lambda_{5})\mathbf{e}_{1}\mathbf{e}_{1}^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+(\lambda_{2}+\lambda_{3}+\lambda_{4}+\lambda_{5})\,\mathbf{e}_{2}\mathbf{e}_{2}^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+(\lambda_{2}+\lambda_{3}+\lambda_{5})\,\mathbf{e}_{1}\mathbf{e}_{2}^{T}+(\lambda_{2}+\lambda_{3}+\lambda_{5})\,\mathbf{e}_{2}\mathbf{e}_{1}^{T}$} \nonumber 
&\quad \scalebox{0.9}{$+(\delta_{1}+\delta_{2}+\delta_{3}+\delta_{5})\,\boldsymbol{\rho}_{1}\boldsymbol{\rho}_{1}^{T}+(\eta_{2}+\eta_{3}+\eta_{4}+\eta_{5})\,\boldsymbol{\rho}_{2}\boldsymbol{\rho}_{2}^{T}$}.
\end{align}
Then, we use additional scalar factor as follows: $L_{i} \triangleq \scalebox{0.9}{$\frac{2\pi^{2}N_s(N_s^{2}-1)}{3\sigma^{2}c^{2}}(\Delta f)^{2}|\alpha_{i}|^{2}$}$ and 
$\mathbf{M}_{i} \triangleq \mathbf{G}_{i}^{H}\mathbf{G}_{i}$.
Thus, we can obtain:
\begin{align}
\lambda_{1} &= \scalebox{0.9}{$\frac{8\pi^{2}N_s(N_s^{2}-1)}{3\sigma^{2}c^{2}}(\Delta f)^{2}|\alpha_{1}|^{2}\mathrm{tr}\{\mathbf{G}_{1}\mathbf{R}_{x1}\mathbf{G}_{1}^{H}\}$} \nonumber 
&= \scalebox{0.9}{$4L_{1}\,\mathrm{tr}\{\mathbf{M}_{1}\mathbf{R}_{x1}\}$},
\end{align}
Analogous expressions can be derived $\lambda_{2} = L_{2}\mathrm{tr}\{\mathbf{M}_{2}\mathbf{R}_{X1}\},$
$\lambda_{3} = L_{3}\mathrm{tr}\{\mathbf{M}_{3}\mathbf{R}_{X1}\},$
$\lambda_{4} = 4L_{4}\mathrm{tr}\{\mathbf{M}_{4}\mathbf{R}_{X2}\}$ and
$\lambda_{5} = L_{5}\mathrm{tr}\{\mathbf{M}_{5}\mathbf{R}_{X2}\}$. Thus the equivalent FIM is:
\begin{flalign}
\mathbf{J}_e &= \begin{bmatrix}
J_{1,1} & J_{1,2} 
J_{1,2} & J_{2,2}
\end{bmatrix} = \boldsymbol{\Xi}^{T} \mathbf{J}_{m} \boldsymbol{\Xi}\nonumber 
&= \scalebox{0.9}{$\big( 4 L_1\operatorname{tr}\{\mathbf{M}_1\mathbf{R}_{x1}\}  
+ L_2\operatorname{tr}\{\mathbf{M}_2\mathbf{R}_{x1}\}$} + L_3\operatorname{tr}\{\mathbf{M}_3\mathbf{R}_{x1}\} 
\nonumber 
&\quad \scalebox{0.9}{$+ 4L_4\operatorname{tr}\{\mathbf{M}_4\mathbf{R}_{x2}\}+ L_5\operatorname{tr}\{\mathbf{M}_5\mathbf{R}_{x2}\}\big)
\mathbf{e}_{1}\mathbf{e}_{1}^{T}$}
\nonumber [4pt]
&\quad + \scalebox{0.9}{$\big( L_2\operatorname{tr}\{\mathbf{M}_2\mathbf{R}_{x1}\}
+ L_3\operatorname{tr}\{\mathbf{M}_3\mathbf{R}_{x1}\}$} \nonumber 
&\quad \scalebox{0.9}{$+ 4L_4\operatorname{tr}\{\mathbf{M}_4\mathbf{R}_{x2}\}
+ L_5\operatorname{tr}\{\mathbf{M}_5\mathbf{R}_{x2}\}\big)
\mathbf{e}_{2}\mathbf{e}_{2}^{T}$}
+ \hdots
\end{flalign}
After collecting the coefficients of the feasible covariance vector $\mathbf r=[\mathbf r_1^T,\mathbf r_2^T]^T$, each real EFIM entry is linear in $\mathbf r$. Hence, there exist coefficient vectors $\mathbf c_{11}$, $\mathbf c_{22}$, and $\mathbf c_{12}$ such that
\begin{equation}
J_{11}=\mathbf c_{11}^H\mathbf r,\qquad J_{22}=\mathbf c_{22}^H\mathbf r,\qquad J_{12}=\mathbf c_{12}^H\mathbf r,
\end{equation}
with real values on the feasible Hermitian covariance set. The coefficient vectors contain the contributions of both $\mathbf r_1$ and $\mathbf r_2$. Defining
\begin{equation}
\mathbf m\triangleq\frac{\mathbf c_{11}+\mathbf c_{22}}{2},\qquad
\widetilde{\mathbf B}\triangleq\frac{\mathbf c_{11}\mathbf c_{22}^H+\mathbf c_{22}\mathbf c_{11}^H}{2}-\mathbf c_{12}\mathbf c_{12}^H,
\label{eq:ND}
\end{equation}
we obtain
\begin{equation}
\operatorname{CRB}=\frac{J_{11}+J_{22}}{J_{11}J_{22}-J_{12}^2}
=\frac{\mathbf r^H\mathbf m+\mathbf m^H\mathbf r}{\mathbf r^H\widetilde{\mathbf B}\mathbf r}.
\label{eq:CRB-end}
\end{equation}
The off-diagonal blocks of $\widetilde{\mathbf B}$ explicitly generate the $\mathbf r_1$--$\mathbf r_2$ cross terms. No positive-semidefiniteness of $\widetilde{\mathbf B}$ is assumed, which motivates the spectral split used in Section IV-B.
\section{Calculation of the CRB in terms of $\phi$}
\label{app:B}
For fixed $\mathbf A$ and $\mathbf A_a$, the phase vector affects the radar FIM through Path~3. Define
\begin{align}
\mathbf d_0&\triangleq\overline{\mathbf c(\theta_4)}\odot(\mathbf I-\mathbf A)\mathbf c(\theta_5),
\mathbf d_1&\triangleq\overline{\mathbf c(\theta_4)}\odot(\mathbf I-\mathbf A)\dot{\mathbf c}(\theta_5),
\end{align}
where $\dot{\mathbf c}(\theta_5)=\partial\mathbf c(\theta_5)/\partial\theta_2$ and $\partial\theta_5/\partial\theta_2=1$. From \eqref{eq:gain_g},
\begin{equation}
g=\mathbf d_0^T\boldsymbol\phi,\qquad
\frac{\partial g}{\partial\theta_2}=\mathbf d_1^T\boldsymbol\phi.
\end{equation}
Hence
\begin{equation}
S_0(\boldsymbol\phi)=|g|^2=\boldsymbol\phi^H\mathbf Q_0\boldsymbol\phi,\qquad
S_1(\boldsymbol\phi)=\left|\frac{\partial g}{\partial\theta_2}\right|^2=\boldsymbol\phi^H\mathbf Q_1\boldsymbol\phi,
\end{equation}
where $\mathbf Q_0=\mathbf d_0^*\mathbf d_0^T$ and $\mathbf Q_1=\mathbf d_1^*\mathbf d_1^T$. The Path-3 delay information and its $\theta_1$ contribution are affine in $S_0$, whereas the Path-3 contribution to the $\theta_2$ information is affine in $S_1$. Consequently, the position-EFIM entries can be written as
\begin{equation}
J_{ij}(\boldsymbol\phi)=\beta^{(0)}_{ij}S_0(\boldsymbol\phi)+\beta^{(1)}_{ij}S_1(\boldsymbol\phi)+\lambda_{ij},
\end{equation}
for $(i,j)\in\{(1,1),(1,2),(2,2)\}$, where the coefficients collect the phase-independent terms. Therefore,
\begin{equation}
\operatorname{CRB}(\boldsymbol\phi)=F\!\left(S_0(\boldsymbol\phi),S_1(\boldsymbol\phi)\right)
=\frac{J_{11}(\boldsymbol\phi)+J_{22}(\boldsymbol\phi)}{J_{11}(\boldsymbol\phi)J_{22}(\boldsymbol\phi)-J_{12}^2(\boldsymbol\phi)}.
\label{CRB-phi}
\end{equation}
At iteration $t$, the local SCA model used in Section IV-C is obtained from the first-order expansion
\begin{equation}
F(S_0,S_1)\approx F(s_{0,t},s_{1,t})+\mu_{0,t}(S_0-s_{0,t})+\mu_{1,t}(S_1-s_{1,t}),
\end{equation}
where $s_{q,t}=S_q(\boldsymbol\phi^{(t)})$ and $\mu_{q,t}=\partial F/\partial S_q|_{(s_{0,t},s_{1,t})}$, $q\in\{0,1\}$. The acceptance rule in Section IV-C is applied to the original fixed-penalty objective rather than treating this local expansion as a global MM upper bound.
